crossings_with_signal_1 = [c for c in crossings if c.get("signal_id") == "signal_1"]
if not crossings_with_signal_1:
    raise ValueError("No crossing found with signal_1")

cid, road, s = crossings_with_signal_1[0]["id"], crossings_with_signal_1[0]["road"], crossings_with_signal_1[0]["road_s"]
length = MAP.road(road)["length"]

# Define signal cycle for signal_1 (must happen before ScenarioBuilder)
signal_name = MAP.signal_cycle(cid, green=15, red=20, initial="red")

scenario = ScenarioBuilder("look_then_cross", MAP, scenario_type="custom",
                           description="Look at an approaching car, then cross the road.")

# User starts at the 'start' side of the crossing
scenario.user(MAP.crossing_side(cid, "start", inset=2.0))

# Create the approaching car
route = MAP.drive_route(road, s, min(length, s + 50), "forward")
scenario.vehicle("Car1", route[0], route[1:], speed=8.0, model="car_white", start_when=when_task_starts(None))

