from usg.dsl import *

# Find the zebra crossing (crossing_258)
crossings = MAP.crossings(control="zebra") or MAP.crossings()
crossing_258 = None
for c in crossings:
    if c["id"] == "crossing_258":
        crossing_258 = c
        break

if crossing_258 is None:
    raise ValueError("No zebra crossing found")

# Get road details
road_id = crossing_258["road"]
road = MAP.road(road_id)
length = road["length"]
s = road.get("road_s", 0)

# Build the scenario
scenario = ScenarioBuilder("cross_at_zebra", MAP, scenario_type="dyn_nav",
                           description="Cross a zebra crossing while a car approaches; avoid it.")

# User starts at the start side of the crossing
scenario.user(MAP.crossing_side(crossing_258["id"], "start", inset=2.0))

# Create the vehicle (Car1) on the road
# Use MAP.along_road to get a Place object for the start position
start_place = MAP.along_road(road_id, s)
end_place = MAP.along_road(road_id, max(0.0, s - 30.0))
route = MAP.drive_route(road_id, start_place, end_place, "forward")
scenario.vehicle("Car1", route[0], route[1:], speed=8.0, model="car_white", start_when=when_task_starts(None))

# Create the signal cycle for signal_53
signal_name = "signal_53"
scenario.signal_cycle(signal_name, green=15, red=20, initial="red")

# Apply the specification
handles = scenario.apply_spec({
    "tasks": [
        {
            "name": "cross_at_zebra",
            "instruction": "Wait for the car to pass, then cross the zebra crossing.",
            "goal": {
                "op": "call",
                "name": "cross",
                "args": {
                    "far_zone": {
                        "kind": "crossing_side",
                        "id": "crossing_258",
                        "side": "end",
                        "r": 2
                    }
                }
            },
            "safety": [
                {
                    "op": "call",
                    "name": "collision_free",
                    "args": {
                        "entity": "Car1",
                        "r": 0.3
                    }
                },
                {
                    "op": "and",
                    "args": [
                        {
                            "op": "call",
                            "name": "wait_for_green",
                            "args": {
                                "zone": {
                                    "kind": "crossing_side",
                                    "id": "crossing_258",
                                    "side": "start",
                                    "r": 2
                                },
                                "signal": "signal_53"
                            }
                        }
                    ]
                }
            ],
            "timeout": {
                "initial": 60,
                "baseline": 90
