# Select a signalised crossing for the task
crossings = MAP.crossings(control="signals")
cr = sorted(crossings, key=lambda c: (MAP.road(c["road"])["oneway"], -MAP.road(c["road"])["lanes"]))[0]
cid, road, s = cr["id"], cr["road"], cr["road_s"]

# Ensure signal_1 exists for the task; create it if not present
signal_name = "signal_1"
try:
    MAP.signal(signal_name)
except:
    signal_name = scenario.signal_cycle(cid, green=15, red=20, initial="red")

